def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    marker = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    for r in range(h):
        ps=[c for c,v in enumerate(grid[r]) if v==marker]
        for a,b in zip(ps,ps[1:]):
            for c in range(a+1,b): out[r][c]=3
    for c in range(w):
        ps=[r for r in range(h) if grid[r][c]==marker]
        for a,b in zip(ps,ps[1:]):
            for r in range(a+1,b): out[r][c]=3
    return out
